// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;

    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 amount, bytes32 payloadSeed) public {
        amount = bound(amount, 0, 1 ether);

        Reverter bad = new Reverter();

        vm.deal(address(c), 1 ether);

        bytes memory data = abi.encodePacked(payloadSeed);

        bool ok;
        try c.sendMoney(address(bad), amount, data) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok == false);
    }
}

contract Reverter {
    fallback() external payable {
        revert("revert");
    }
    receive() external payable {
        revert("revert");
    }
}
